    if x <= 1.0:
        return float('-inf')
    lnx = math.log(x)
    result = _EULER_GAMMA + math.log(lnx)
    term = 1.0
    for k in range(1, 200):
        term *= lnx / k
        contrib = term / k
        result += contrib
        if abs(contrib) < 1e-15 * max(1.0, abs(result)):
            break
    return result

def _R(x):
    if x <= 1:
        return 0.0
    result = 0.0
    for k in range(1, len(_MU)):
        if _MU[k] == 0:
            continue
        xk = x ** (1.0 / k)
        if xk <= 1.001:
            break
        result += _MU[k] / k * _li(xk)
    return result

def _R_inverse(n):
    if n <= 1:
        return 2.0
    x = float(n) * math.log(n)
    if n > 5:
        x = float(n) * (math.log(n) + math.log(math.log(n)))
    for _ in range(100):
        x = max(x, 2.0)
        r = _R(x)
        err = n - r
        if abs(err) < 1e-8:
            break
        dx = err * math.log(x)
        x += dx
        x = max(x, 2.0)
        if abs(dx) < 1e-8:
